// Minimal client-side search over /index.json (generated by layouts/index.json).
// Ranks by title > tags > summary > content; every query term must match somewhere.
(function () {
  var script = document.currentScript;
  var indexURL = script && script.getAttribute("data-index");
  var input = document.getElementById("search-input");
  var results = document.getElementById("search-results");
  var status = document.getElementById("search-status");
  if (!input || !indexURL) return;

  var docs = null;

  function norm(s) { return (s || "").toLowerCase(); }

  function escapeHTML(s) {
    return s.replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }

  function highlight(text, terms) {
    var html = escapeHTML(text);
    if (!terms.length) return html;
    var re = new RegExp("(" + terms.map(function (t) { return escapeRe(escapeHTML(t)); }).join("|") + ")", "gi");
    return html.replace(re, "<mark>$1</mark>");
  }

  function count(hay, term) {
    var n = 0, i = 0;
    while ((i = hay.indexOf(term, i)) !== -1) { n++; i += term.length; }
    return n;
  }

  function snippet(doc, terms) {
    var text = doc.content || "";
    var lower = norm(text);
    var pos = -1;
    for (var i = 0; i < terms.length && pos < 0; i++) pos = lower.indexOf(terms[i]);
    if (pos < 0) return doc.summary || text.slice(0, 200);
    var start = Math.max(0, pos - 80);
    var end = Math.min(text.length, pos + 160);
    if (start > 0) { var sp = text.indexOf(" ", start); if (sp > -1 && sp < pos) start = sp + 1; }
    if (end < text.length) { var ep = text.lastIndexOf(" ", end); if (ep > pos) end = ep; }
    return (start > 0 ? "… " : "") + text.slice(start, end).trim() + (end < text.length ? " …" : "");
  }

  function search(q) {
    var terms = norm(q).split(/\s+/).filter(Boolean);
    if (!terms.length) return [];
    var out = [];
    docs.forEach(function (d) {
      var score = 0;
      for (var i = 0; i < terms.length; i++) {
        var t = terms[i];
        var s = 0;
        if (d._title.indexOf(t) > -1) s += 10 + (d._title.indexOf(t) === 0 ? 2 : 0);
        if (d._tags.indexOf(t) > -1) s += 6;
        if (d._summary.indexOf(t) > -1) s += 3;
        var c = count(d._content, t);
        if (c) s += 1 + Math.min(c, 10) * 0.3;
        if (!s) return; // all terms required
        score += s;
      }
      out.push({ doc: d, score: score });
    });
    out.sort(function (a, b) { return b.score - a.score; });
    return out.map(function (r) { return r.doc; });
  }

  function render() {
    var q = input.value.trim();
    var terms = norm(q).split(/\s+/).filter(Boolean);
    results.innerHTML = "";
    if (!q) { status.textContent = ""; return; }
    var hits = search(q);
    status.textContent = hits.length ? hits.length + (hits.length === 1 ? " result" : " results") : "No results for “" + q + "”.";
    hits.slice(0, 30).forEach(function (d) {
      var li = document.createElement("li");
      li.innerHTML =
        '<a class="r-title" href="' + d.url + '">' + highlight(d.title, terms) + "</a>" +
        '<p class="r-snippet">' + highlight(snippet(d, terms), terms) + "</p>" +
        '<div class="r-meta">' + escapeHTML(d.date) +
        (d.tags && d.tags.length ? " · " + d.tags.map(escapeHTML).join(", ") : "") + "</div>";
      results.appendChild(li);
    });
  }

  function syncURL() {
    var q = input.value.trim();
    var url = new URL(window.location.href);
    if (q) url.searchParams.set("q", q); else url.searchParams.delete("q");
    history.replaceState(null, "", url);
  }

  var timer;
  input.addEventListener("input", function () {
    clearTimeout(timer);
    timer = setTimeout(function () { if (docs) render(); syncURL(); }, 80);
  });

  status.textContent = "Loading index…";
  fetch(indexURL)
    .then(function (r) { return r.json(); })
    .then(function (data) {
      docs = data.map(function (d) {
        d._title = norm(d.title);
        d._tags = norm((d.tags || []).join(" "));
        d._summary = norm(d.summary);
        d._content = norm(d.content);
        return d;
      });
      var q = new URLSearchParams(window.location.search).get("q");
      if (q) input.value = q;
      status.textContent = "";
      render();
    })
    .catch(function () { status.textContent = "Could not load the search index."; });

  // Press "/" anywhere on the page to focus the search box.
  document.addEventListener("keydown", function (e) {
    if (e.key === "/" && document.activeElement !== input) { e.preventDefault(); input.focus(); }
  });
})();
